import os, subprocess, shutil
PRISTINE='/tmp/orig'
TC='/tmp/tc'
FILES=['ACCOUNTS.DAT','BOOKS.DAT','TRANSACTIONS.DAT']
def setup(input_bytes, pristine=PRISTINE):
    for f in FILES:
        shutil.copy(os.path.join(pristine,f), os.path.join(TC,'data',f))
    open(os.path.join(TC,'src','INPUT.DAT'),'wb').write(input_bytes)
def snap():
    out={}
    for f in FILES:
        p=os.path.join(TC,'data',f)
        out[f]=open(p,'rb').read() if os.path.exists(p) else None
    return out
def run_cobol(inp, pristine=PRISTINE):
    setup(inp, pristine)
    r=subprocess.run(['/tmp/prog'], cwd=TC, capture_output=True)
    return r, snap()
